function [s,dossier,machine] = comput_dke_yp%%%	Computer look-up for data management%%	Input: none%%	Output:%%		- s: separator used for the machine (string) [1,1]%		- dossier: root directory (string) [1,m]%		- machine: computer name (string) [1,m]%%by Y.PEYSSON CEA-DRFC 05/12/94 <yves.peysson@cea.fr>%revised for MatLab 5.2 (31/08/2000) %revised for MatLab 6.5 (17/07/2003)  % machine = computer;if strcmp(machine,'ALPHA') == 1,	s = '/';	dossier = '/usr/drfc/peysson';elseif strcmp(machine,'PC') == 1,	s = '\';   	dossier = 'c:\';elseif strcmp(machine,'MAC') == 1,	s = '/';   	dossier = '/Volumes/Ailefroide/CVS/Project_DKE';end